def find_horizontal_segments(arr):
    segments = []
    for r in range(arr.shape[0]):
        row = list(arr[r])
        c = 0
        while c < len(row):
            if row[c] != 9:
                seg_color = row[c]
                seg_count = 1
                for j in range(c+1, len(row)):
                    if row[j] == seg_color:
                        seg_count += 1
                    else:
                        break
                if seg_count >= 3:
                    segments.append((seg_color, r, c, seg_count))
                c += seg_count
            else:
                c += 1
    return segments

